export const validId=v=>typeof v==='string'&&/^[a-f0-9-]{36}$/.test(v);
const finite=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;
export function validateObjects(items){if(!Array.isArray(items)||items.length>12)throw Error('房间最多保留 12 件新增作品');const seen=new Set();return items.map(o=>{if(!o||!validId(o.id)||!validId(o.asset)||seen.has(o.id)||typeof o.name!=='string'||!o.name.trim()||o.name.length>50||!['decor','seat','sofa'].includes(o.kind)||![0,1].includes(o.floor)||!finite(o.x,-4.2,4.2)||!finite(o.z,-3,3)||!finite(o.yaw,-Math.PI,Math.PI)||!finite(o.width,.15,2.5)||!finite(o.height,.1,1.8)||!finite(o.depth,.15,1.3)||!finite(o.seat,.15,.9)||!/^#[a-fA-F0-9]{6}$/.test(o.tint)||o.description!==undefined&&(typeof o.description!=='string'||o.description.length>1024)||Object.keys(o).some(k=>!['id','asset','name','kind','floor','x','z','yaw','width','height','depth','seat','tint','description'].includes(k)))throw Error('家具参数不正确');seen.add(o.id);return {...o}})}
export function validateTailoring(v){if(v==null)return null;if(!v||!['skirt','dress','top'].includes(v.kind)||typeof v.name!=='string'||!v.name.trim()||v.name.length>50||!['plain','check','stripe','dots'].includes(v.pattern)||!/^#[a-fA-F0-9]{6}$/.test(v.color)||!/^#[a-fA-F0-9]{6}$/.test(v.accent)||!finite(v.length,.18,.4)||!finite(v.flare,.02,.13)||!Number.isInteger(v.pleats)||v.pleats<0||v.pleats>24||!finite(v.patternScale,.03,.12)||Object.keys(v).some(k=>!['kind','name','pattern','color','accent','length','flare','pleats','patternScale'].includes(k)))throw Error('服饰结构不正确');return {...v}}
